1	import React from "react";
2	import { call, on } from "../../api.js";
3	import TestPanel, { useNow, useStickyScroll } from "./TestPanel.jsx";
4	import {
5	  CheckIcon,
6	  Icon,
7	  PHASES,
8	  ROLE,
9	  Status,
10	  fmtDuration,
11	  fmtMoney,
12	  latestVerdict,
13	  modSpend,
14	  phaseIndex,
15	  shortModel,
16	} from "./shared.jsx";
17	
18	const EXAMPLES = [
19	  "A golden sword that launches any mob it hits into the sky with particles, with a 3 second cooldown.",
20	  "Arrows that explode on impact without breaking blocks, with a 5 second cooldown per player.",
21	  "Right-clicking with a blaze rod shoots a fireball where you look.",
22	];
23	
24	const STEP_DETAIL = {
25	  spec: "Turn the idea into a plugin spec and an in-game test plan",
26	  repo: "Create the mod repository with Entire and Neatlogs hooks",
27	  build: "Write the Paper plugin",
28	  compile: "Package it with Maven",
29	  deploy: "Load it on the Paper server",
30	  playtest: "An AI player runs every check in-game",
31	  fix: "Patch failures from the evidence, up to 3 attempts",
32	  done: "Report the result",
33	};
34	
35	export default function BuildPage({ mod, running, lessons, onCreated, onWatch, onNew, onOpenCode }) {
36	  const [prompt, setPrompt] = React.useState("");
37	  return (
38	    <div className="build-chat">
39	      <section className="chat">
40	        <ChatHead mod={mod} onNew={onNew} onOpenCode={onOpenCode} />
41	        {mod ? <Thread mod={mod} onOpenCode={onOpenCode} /> : <Welcome lessons={lessons} onPick={setPrompt} />}
42	        <Composer
43	          mod={mod}
44	          running={running}
45	          prompt={prompt}
46	          setPrompt={setPrompt}
47	          onCreated={onCreated}
48	          onWatch={onWatch}
49	        />
50	      </section>
51	      <TestPanel mod={mod} building={Boolean(running)} />
52	    </div>
53	  );
54	}
55	
56	function ChatHead({ mod, onNew, onOpenCode }) {
57	  return (
58	    <header className="chat-head">
59	      <div className="chat-title">
60	        {mod ? (
61	          <>
62	            <strong>{mod.name}</strong>
63	            <Status status={mod.running ? "running" : mod.status} />
64	            {mod.seed && <span className="tag">Seeded bug</span>}
65	          </>
66	        ) : (
67	          <strong>New mod</strong>
68	        )}
69	      </div>
70	      {mod && (
71	        <div className="page-actions">
72	          {mod.running && (
73	            <button className="btn danger sm" onClick={() => call("studio:stop", { id: mod.id })}>
74	              <Icon name="stop" size={13} />
75	              Stop
76	            </button>
77	          )}
78	          {mod.repoDir && (
79	            <button className="btn sm" onClick={() => onOpenCode(mod.id)}>
80	              <Icon name="code" size={13} />
81	              Code
82	            </button>
83	          )}
84	          {!mod.running && (
85	            <button className="btn sm" onClick={onNew}>
86	              <Icon name="plus" size={13} />
87	              New
88	            </button>
89	          )}
90	        </div>
91	      )}
92	    </header>
93	  );
94	}
95	
96	function Welcome({ lessons, onPick }) {
97	  return (
98	    <div className="thread welcome-wrap">
99	      <div className="intro">
100	        <span className="welcome-mark">B</span>
101	        <h1>What should your mod do?</h1>
102	        <p>Describe a gameplay idea. Benana writes the Paper plugin, an AI player tests it on a live server, and a fixer patches anything that breaks.</p>
103	        <div className="ideas">
104	          {EXAMPLES.map((ex) => (
105	            <button key={ex} onClick={() => onPick(ex)}>
106	              <Icon name="spark" size={14} />
107	              <span>{ex}</span>
108	            </button>
109	          ))}
110	        </div>
111	        {lessons.length > 0 && (
112	          <div className="welcome-lessons">
113	            <span className="side-label">
114	              The fixer has learned {lessons.length} lesson{lessons.length === 1 ? "" : "s"}
115	            </span>
116	            <p>{lessons.at(-1).lesson}</p>
117	          </div>
118	        )}
119	      </div>
120	    </div>
121	  );
122	}
123	
124	function Composer({ mod, running, prompt, setPrompt, onCreated, onWatch }) {
125	  const [seed, setSeed] = React.useState(false);
126	  const [busy, setBusy] = React.useState(false);
127	  const [error, setError] = React.useState("");
128	  const ref = React.useRef(null);
129	  const canStart = !busy && !running && (seed || prompt.trim().length >= 8);
130	
131	  React.useLayoutEffect(() => {
132	    const el = ref.current;
133	    if (!el) return;
134	    el.style.height = "auto";
135	    el.style.height = `${Math.min(el.scrollHeight, 180)}px`;
136	  }, [prompt]);
137	
138	  const start = async () => {
139	    if (!canStart) return;
140	    setBusy(true);
141	    setError("");
142	    try {
143	      const created = await call("studio:create", { prompt, seed });
144	      setPrompt("");
145	      onCreated(created.id);
146	    } catch (e) {
147	      setError(e.message);
148	    } finally {
149	      setBusy(false);
150	    }
151	  };
152	
153	  return (
154	    <div className="composer-wrap">
155	      {mod?.running && <Dock mod={mod} />}
156	      {running && running.id !== mod?.id && (
157	        <button className="dock dock-link" onClick={() => onWatch(running.id)}>
158	          <span className="spinner" />
159	          <span>
160	            <strong>{running.name}</strong> is building
161	          </span>
162	          <span className="dock-cta">
163	            Watch <Icon name="arrow" size={13} />
164	          </span>
165	        </button>
166	      )}
167	      {error && <div className="alert">{error}</div>}
168	      <div className={`chat-input ${seed ? "seeded" : ""} ${running ? "locked" : ""}`}>
169	        <textarea
170	          ref={ref}
171	          rows={1}
172	          value={prompt}
173	          disabled={seed}
174	          aria-label="Describe a mod"
175	          placeholder={
176	            running ? "One mod builds at a time. Describe the next one…" : mod ? "Describe another mod…" : "A golden sword that launches mobs into the sky…"
177	          }
178	          onChange={(e) => setPrompt(e.target.value)}
179	          onKeyDown={(e) => {
180	            if (e.key === "Enter" && !e.shiftKey) {
181	              e.preventDefault();
182	              start();
183	            }
184	          }}
185	        />
186	        <div className="chat-input-bar">
187	          <label className="toggle" title="Attempt 1 starts from a labeled buggy fixture. The playtester and fixer still run for real.">
188	            <input type="checkbox" checked={seed} onChange={(e) => setSeed(e.target.checked)} />
189	            <span className="switch" />
190	            Seeded bug
191	          </label>
192	          <span className="input-hint">{running ? "Waiting for the current build" : "Enter to build · Shift+Enter for a new line"}</span>
193	          <button className="send" disabled={!canStart} onClick={start} aria-label="Build and playtest" title="Build and playtest">
194	            {busy ? <span className="spinner dark" /> : <Icon name="send" size={16} />}
195	          </button>
196	        </div>
197	      </div>
198	    </div>
199	  );
200	}
201	
202	function Dock({ mod }) {
203	  const now = useNow(true);
204	  const i = phaseIndex(mod);
205	  const label = PHASES[i]?.[1] || "Working";
206	  const verdict = latestVerdict(mod);
207	  const total = mod.testPlan?.checks.length || 0;
208	  const done = (verdict?.checks || []).length;
209	  const attempt = mod.attempts.at(-1);
210	  const since = attempt?.startedAt || mod.updatedAt || mod.createdAt;
211	  const who =
212	    mod.phase === "playtest" ? "The AI player is testing in-game" : mod.phase === "fix" ? "The fixer is patching the plugin" : `${label} in progress`;
213	  return (
214	    <div className="dock">
215	      <span className="spinner" />
216	      <span className="dock-text">
217	        <strong>{who}</strong>
218	        <small>
219	          Step {i + 1} of {PHASES.length} · {label}
220	          {attempt ? ` · attempt ${attempt.n}` : ""}
221	        </small>
222	      </span>
223	      {total > 0 && (
224	        <span className="dock-checks">
225	          {done}/{total} checks
226	        </span>
227	      )}
228	      <span className="dock-time">{fmtDuration(now - since)}</span>
229	    </div>
230	  );
231	}
232	
233	/* ---------- Thread ---------- */
234	
235	function useFeed(mod) {
236	  const [feed, setFeed] = React.useState([]);
237	  const idRef = React.useRef(mod.id);
238	  idRef.current = mod.id;
239	  React.useEffect(
240	    () =>
241	      on("studio:feed", ({ modId, item }) => {
242	        if (modId === idRef.current) setFeed((prev) => [...prev.slice(-799), item]);
243	      }),
244	    [],
245	  );
246	  React.useEffect(() => {
247	    setFeed([]);
248	    call("studio:get", { id: mod.id })
249	      .then((full) => setFeed(full.feed.slice(-800)))
250	      .catch(() => {});
251	  }, [mod.id]);
252	  return feed;
253	}
254	
255	function buildThread(mod, feed) {
256	  const items = [{ type: "user", key: "user" }, { type: "plan", key: "plan" }];
257	  let turn = null;
258	  feed.forEach((f, i) => {
259	    const key = `${f.at}-${i}`;
260	    if (f.kind === "session") return;
261	    if (f.role === "benana") {
262	      turn = null;
263	      if (f.kind === "phase") items.push({ type: "phase", key, f });
264	      else if (f.kind === "failure" || f.kind === "error") items.push({ type: "alert", key, f });
265	      else items.push({ type: "note", key, f });
266	      return;
267	    }
268	    if (f.kind === "plan") {
269	      items.push({ type: "testplan", key, bare: turn?.role === "spec" });
270	      turn = null;
271	      return;
272	    }
273	    const id = `${f.role}:${f.attempt || 0}`;
274	    if (!turn || turn.id !== id) {
275	      turn = { type: "turn", key, id, role: f.role, attempt: f.attempt || null, entries: [] };
276	      items.push(turn);
277	    }
278	    turn.entries.push(f);
279	  });
280	  if (!feed.some((f) => f.kind === "plan") && mod.testPlan) items.splice(2, 0, { type: "testplan", key: "tp" });
281	  if (!mod.running && ["passed", "failed", "stopped"].includes(mod.status)) items.push({ type: "result", key: "result" });
282	  return items;
283	}
284	
285	function Thread({ mod, onOpenCode }) {
286	  const feed = useFeed(mod);
287	  const items = React.useMemo(() => buildThread(mod, feed), [mod, feed]);
288	  const { ref, onScroll, away, jump } = useStickyScroll(`${items.length}:${feed.length}:${mod.updatedAt}`);
289	  const lastTurn = [...items].reverse().find((x) => x.type === "turn");
290	
291	  return (
292	    <div className="thread" ref={ref} onScroll={onScroll}>
293	      <div className="thread-inner">
294	        {items.map((it) => {
295	          switch (it.type) {
296	            case "user":
297	              return (
298	                <div key={it.key} className="msg-user">
299	                  <div className="bubble">{mod.prompt}</div>
300	                </div>
301	              );
302	            case "plan":
303	              return (
304	                <Turn key={it.key} role="benana" title="Benana" meta="Plan">
305	                  <p className="prose">I'll build this as a Paper plugin and test it with an AI player. This list updates as each step finishes.</p>
306	                  <PipelineChecklist mod={mod} />
307	                </Turn>
308	              );
309	            case "testplan":
310	              return <TestPlanChecklist key={it.key} mod={mod} bare={it.bare} />;
311	            case "phase":
312	              return <PhaseLine key={it.key} f={it.f} mod={mod} />;
313	            case "note":
314	              return (
315	                <div key={it.key} className={`note-line ${/Entire checkpoint/.test(it.f.text) ? "entire" : ""}`}>
316	                  <Icon name="info" size={13} />
317	                  <span>{it.f.text}</span>
318	                </div>
319	              );
320	            case "alert":
321	              return (
322	                <div key={it.key} className="alert-card">
323	                  <CheckIcon status="fail" />
324	                  <div>
325	                    <strong>{it.f.kind === "error" ? "Run error" : `Attempt ${it.f.attempt} failed`}</strong>
326	                    <p>{it.f.text.replace(/^Attempt \d+ failed \(\w+\): /, "")}</p>
327	                  </div>
328	                </div>
329	              );
330	            case "turn":
331	              return <AgentTurn key={it.key} turn={it} mod={mod} live={mod.running && it === lastTurn} />;
332	            case "result":
333	              return <ResultCard key={it.key} mod={mod} onOpenCode={onOpenCode} />;
334	            default:
335	              return null;
336	          }
337	        })}
338	      </div>
339	      {away && (
340	        <button className="jump" onClick={jump}>
341	          Jump to latest
342	        </button>
343	      )}
344	    </div>
345	  );
346	}
347	
348	const AVATAR = { benana: "B", spec: "S", builder: "Bu", playtester: "P", fixer: "F" };
349	
350	function Turn({ role, title, meta, children }) {
351	  return (
352	    <div className="turn">
353	      <div className="turn-head">
354	        <span className={`role-avatar ${role}`}>{AVATAR[role] || role[0]?.toUpperCase()}</span>
355	        <strong>{title}</strong>
356	        {meta && <span className="meta">{meta}</span>}
357	      </div>
358	      <div className="turn-body">{children}</div>
359	    </div>
360	  );
361	}
362	
363	function sessionFor(mod, role, attemptN) {
364	  if (role === "spec") return mod.sessions.find((s) => s.role === "spec");
365	  const a = mod.attempts.find((x) => x.n === attemptN);
366	  return a?.sessions.filter((s) => s.role === role).at(-1);
367	}
368	
369	function AgentTurn({ turn, mod, live }) {
370	  const s = sessionFor(mod, turn.role, turn.attempt);
371	  const meta = [
372	    turn.attempt ? `attempt ${turn.attempt}` : null,
373	    s?.model ? shortModel(s.model) : null,
374	    s?.endedAt && s?.startedAt ? fmtDuration(s.endedAt - s.startedAt) : null,
375	    s?.usage?.costUsd ? fmtMoney(s.usage.costUsd) : null,
376	  ]
377	    .filter(Boolean)
378	    .join(" · ");
379	
380	  const groups = [];
381	  for (const e of turn.entries) {
382	    const isWork = e.kind === "tool" || e.kind === "result" || e.kind === "note";
383	    const last = groups.at(-1);
384	    if (isWork && last?.work) last.entries.push(e);
385	    else if (isWork) groups.push({ work: true, entries: [e] });
386	    else groups.push({ work: false, entries: [e] });
387	  }
388	
389	  return (
390	    <Turn role={turn.role} title={ROLE[turn.role] || turn.role} meta={meta}>
391	      {groups.map((g, i) =>
392	        g.work ? (
393	          <WorkLog key={i} entries={g.entries} mod={mod} live={live && i === groups.length - 1} />
394	        ) : (
395	          <Markdown key={i} text={g.entries[0].text} />
396	        ),
397	      )}
398	    </Turn>
399	  );
400	}
401	
402	function parseSummary(summary) {
403	  if (!summary) return {};
404	  try {
405	    return JSON.parse(summary);
406	  } catch {
407	    const pick = (k) => summary.match(new RegExp(`"${k}":"([^"]*)"`))?.[1];
408	    return { id: pick("id"), status: pick("status"), observed: pick("observed"), file_path: pick("file_path"), command: pick("command") };
409	  }
410	}
411	
412	const TOOL_ICON = {
413	  Read: "file",
414	  Write: "file",
415	  Edit: "file",
416	  MultiEdit: "file",
417	  Bash: "terminal",
418	  Grep: "search",
419	  Glob: "search",
420	};
421	
422	function describeArgs(name, summary) {
423	  const args = parseSummary(summary);
424	  if (args.file_path) return args.file_path.replace(/\\/g, "/");
425	  if (args.command) return args.command;
426	  if (args.pattern) return args.pattern;
427	  if (typeof args === "object" && args && Object.keys(args).length) {
428	    return Object.entries(args)
429	      .filter(([, v]) => v != null && v !== "")
430	      .map(([k, v]) => `${k} ${typeof v === "object" ? JSON.stringify(v) : v}`)
431	      .join(" · ")
432	      .slice(0, 160);
433	  }
434	  return summary || "";
435	}
436	
437	function WorkLog({ entries, mod, live }) {
438	  const rows = entries.filter((e) => e.kind !== "result" || e.isError || e.name !== "report_check");
439	  const [open, setOpen] = React.useState(false);
440	  const LIMIT = 4;
441	  const hidden = !open && rows.length > LIMIT + 1 ? rows.length - LIMIT : 0;
442	  const shown = hidden ? rows.slice(-LIMIT) : rows;
443	  const titles = new Map((mod.testPlan?.checks || []).map((c) => [c.id, c.title]));
444	
445	  return (
446	    <div className={`worklog ${live ? "live" : ""}`}>
447	      {hidden > 0 && (
448	        <button className="worklog-more" onClick={() => setOpen(true)}>
449	          {hidden} earlier action{hidden === 1 ? "" : "s"}
450	        </button>
451	      )}
452	      {shown.map((e, i) => {
453	        if (e.kind === "tool" && e.name === "report_check") {
454	          const a = parseSummary(e.summary);
455	          return (
456	            <div key={i} className="work-row check">
457	              <CheckIcon status={a.status} />
458	              <span>
459	                Reported <strong>{titles.get(a.id) || a.id}</strong>
460	                {a.status ? ` · ${a.status}` : ""}
461	              </span>
462	            </div>
463	          );
464	        }
465	        if (e.kind === "tool" && e.name === "finish") {
466	          return (
467	            <div key={i} className="work-row check">
468	              <CheckIcon status="pass" />
469	              <span>Finished the playtest</span>
470	            </div>
471	          );
472	        }
473	        if (e.kind === "result") {
474	          return (
475	            <div key={i} className={`work-row result ${e.isError ? "error" : ""}`}>
476	              <span className="work-arrow">↳</span>
477	              <span className="work-out">{e.text.slice(0, 220)}</span>
478	            </div>
479	          );
480	        }
481	        if (e.kind === "note") {
482	          return (
483	            <div key={i} className="work-row note">
484	              <Icon name="info" size={13} />
485	              <span>{e.text}</span>
486	            </div>
487	          );
488	        }
489	        const isLast = live && i === shown.length - 1;
490	        return (
491	          <div key={i} className="work-row">
492	            {isLast ? <span className="spinner" /> : <Icon name={TOOL_ICON[e.name] || "game"} size={13} />}
493	            <code>{e.name}</code>
494	            <span className="work-args">{describeArgs(e.name, e.summary)}</span>
495	          </div>
496	        );
497	      })}
498	    </div>
499	  );
500	}
501	
502	function PhaseLine({ f, mod }) {
503	  const current = mod.running && mod.phase === f.phase && phaseIndex(mod) === PHASES.findIndex(([k]) => k === f.phase);
504	  return (
505	    <div className={`phase-line ${current ? "current" : ""}`}>
506	      {current ? <span className="spinner" /> : <CheckIcon status="pass" />}
507	      <span>{f.text}</span>
508	    </div>
509	  );
510	}
511	
512	function PipelineChecklist({ mod }) {
513	  const current = phaseIndex(mod);
514	  const passed = mod.status === "passed";
515	  const failed = ["failed", "stopped"].includes(mod.status);
516	  const fixSkipped = passed && !mod.attempts.some((a) => a.role === "fixer");
517	  const doneCount = PHASES.filter((_, i) => passed || i < current).length;
518	  return (
519	    <div className="checklist">
520	      <div className="checklist-head">
521	        <strong>Build plan</strong>
522	        <span className="meta">
523	          {doneCount}/{PHASES.length}
524	        </span>
525	      </div>
526	      <ul>
527	        {PHASES.map(([key, label], i) => {
528	          let state = i < current ? "done" : i === current ? (failed ? "failed" : mod.running ? "active" : "done") : "todo";
529	          if (passed) state = "done";
530	          if (key === "fix" && fixSkipped) state = "skipped";
531	          return (
532	            <li key={key} className={state}>
533	              <StepIcon state={state} />
534	              <span className="step-label">{label}</span>
535	              <span className="step-detail">{state === "skipped" ? "Not needed, passed first try" : STEP_DETAIL[key]}</span>
536	            </li>
537	          );
538	        })}
539	      </ul>
540	    </div>
541	  );
542	}
543	
544	function StepIcon({ state }) {
545	  if (state === "active") return <span className="step-icon active"><span className="spinner" /></span>;
546	  if (state === "done") return <span className="step-icon done"><Icon name="check" size={11} /></span>;
547	  if (state === "failed") return <span className="step-icon failed"><Icon name="x" size={11} /></span>;
548	  if (state === "skipped") return <span className="step-icon skipped" />;
549	  return <span className="step-icon" />;
550	}
551	
552	function TestPlanChecklist({ mod, bare }) {
553	  const verdict = latestVerdict(mod);
554	  const byId = new Map((verdict?.checks || []).map((c) => [c.id, c]));
555	  const checks = mod.testPlan?.checks || [];
556	  const testing = mod.running && mod.phase === "playtest";
557	  const nextId = testing ? checks.find((c) => !byId.has(c.id))?.id : null;
558	  const passing = checks.filter((c) => byId.get(c.id)?.status === "pass").length;
559	  if (!checks.length) return null;
560	  const list = (
561	      <div className="checklist">
562	        <div className="checklist-head">
563	          <strong>Test plan</strong>
564	          <span className="meta">
565	            {passing}/{checks.length} passing
566	          </span>
567	        </div>
568	        <ul>
569	          {checks.map((c) => {
570	            const r = byId.get(c.id);
571	            const state = r ? (r.status === "pass" ? "done" : r.status === "fail" ? "failed" : "blocked") : c.id === nextId ? "active" : "todo";
572	            return (
573	              <li key={c.id} className={`${state} tall`}>
574	                {state === "blocked" ? <CheckIcon status="blocked" /> : <StepIcon state={state} />}
575	                <span className="step-label">{c.title}</span>
576	                <span className="step-detail">{r?.observed || c.expect}</span>
577	              </li>
578	            );
579	          })}
580	        </ul>
581	      </div>
582	  );
583	  if (bare) return <div className="turn-cont">{list}</div>;
584	  return (
585	    <Turn role="spec" title="Spec agent" meta="Test plan">
586	      {mod.spec?.summary && <p className="prose">{mod.spec.summary}</p>}
587	      {list}
588	    </Turn>
589	  );
590	}
591	
592	function ResultCard({ mod, onOpenCode }) {
593	  const passed = mod.status === "passed";
594	  const verdict = latestVerdict(mod);
595	  const checks = verdict?.checks || [];
596	  const lessons = mod.attempts.filter((a) => a.lesson);
597	  const n = mod.attempts.length;
598	  return (
599	    <div className={`result-card ${mod.status}`}>
600	      <div className="result-top">
601	        <span className="result-icon">
602	          <Icon name={passed ? "check" : "x"} size={18} />
603	        </span>
604	        <div>
605	          <strong>
606	            {passed
607	              ? `${mod.name} passed every check${n === 1 ? " on the first attempt" : ` after ${n} attempts`}`
608	              : mod.status === "stopped"
609	                ? `${mod.name} was stopped`
610	                : `${mod.name} still fails after ${n} attempt${n === 1 ? "" : "s"}`}
611	          </strong>
612	          <p>
613	            {checks.filter((c) => c.status === "pass").length}/{mod.testPlan?.checks.length || checks.length} checks passing · {n} attempt
614	            {n === 1 ? "" : "s"} · {fmtMoney(modSpend(mod))}
615	          </p>
616	        </div>
617	      </div>
618	      {lessons.map((a) => (
619	        <div key={a.n} className="lesson">
620	          <span>Lesson from attempt {a.n}</span>
621	          <p>{a.lesson}</p>
622	        </div>
623	      ))}
624	      {mod.repoDir && (
625	        <div className="result-actions">
626	          <button className="btn sm" onClick={() => onOpenCode(mod.id)}>
627	            <Icon name="code" size={13} />
628	            Review the code
629	          </button>
630	          <button className="btn sm" onClick={() => call("open-path", mod.repoDir)}>
631	            <Icon name="folder" size={13} />
632	            Open repository
633	          </button>
634	        </div>
635	      )}
636	    </div>
637	  );
638	}
639	
640	/* ---------- Minimal markdown: paragraphs, bullets, **bold**, `code` ---------- */
641	
642	function inline(text) {
643	  return text.split(/(\*\*[^*]+\*\*|`[^`]+`)/g).map((part, i) =>
644	    part.startsWith("**") && part.endsWith("**") && part.length > 4 ? (
645	      <strong key={i}>{part.slice(2, -2)}</strong>
646	    ) : part.startsWith("`") && part.endsWith("`") && part.length > 2 ? (
647	      <code key={i}>{part.slice(1, -1)}</code>
648	    ) : (
649	      part
650	    ),
651	  );
652	}
653	
654	function Markdown({ text }) {
655	  const blocks = String(text || "")
656	    .replace(/\s+-\s+(?=\*\*)/g, "\n- ")
657	    .split(/\n{2,}/);
658	  return (
659	    <div className="prose">
660	      {blocks.map((block, i) => {
661	        const lines = block.split("\n").filter((l) => l.trim());
662	        const bullets = lines.filter((l) => /^\s*([-*]|\d+\.)\s+/.test(l));
663	        if (bullets.length && bullets.length === lines.length) {
664	          return (
665	            <ul key={i}>
666	              {lines.map((l, j) => (
667	                <li key={j}>{inline(l.replace(/^\s*([-*]|\d+\.)\s+/, ""))}</li>
668	              ))}
669	            </ul>
670	          );
671	        }
672	        if (bullets.length && !/^\s*([-*]|\d+\.)\s+/.test(lines[0])) {
673	          return (
674	            <React.Fragment key={i}>
675	              <p>{inline(lines[0])}</p>
676	              <ul>
677	                {lines.slice(1).map((l, j) => (
678	                  <li key={j}>{inline(l.replace(/^\s*([-*]|\d+\.)\s+/, ""))}</li>
679	                ))}
680	              </ul>
681	            </React.Fragment>
682	          );
683	        }
684	        return (
685	          <p key={i}>
686	            {lines.map((l, j) => (
687	              <React.Fragment key={j}>
688	                {j > 0 && <br />}
689	                {inline(l)}
690	              </React.Fragment>
691	            ))}
692	          </p>
693	        );
694	      })}
