1	// Mod Studio pipeline: prompt -> spec/test plan -> build -> deploy -> playtest -> fix -> retry.
2	// Interface with the game runtime: docs/hackathon/CONTRACTS.md.
3	const fs = require('node:fs');
4	const path = require('node:path');
5	const { appRoot, dataDir } = require('../env.cjs');
6	const game = require('../game/index.cjs');
7	const neatlogs = require('../neatlogs.cjs');
8	const repo = require('./repo.cjs');
9	const prompts = require('./prompts.cjs');
10	const { runClaude, MODELS } = require('./claude.cjs');
11	
12	const MAX_ATTEMPTS = 3;
13	const studioDir = path.join(dataDir, 'studio');
14	const lessonsFile = path.join(studioDir, 'lessons.json');
15	const SEEDED = path.join(appRoot, 'fixtures', 'seeded');
16	
17	const mods = new Map();
18	let active = null; // { modId, stop }
19	let emit = () => {};
20	let log = () => {};
21	
22	const now = () => Date.now();
23	const modFile = (id) => path.join(studioDir, id, 'mod.json');
24	
25	// The newest jar this mod built (Maven overwrites target/<Name>.jar on every attempt).
26	function jarOf(mod) {
27	  const built = [...mod.attempts].reverse().find((a) => a.build?.ok && a.build.jar && fs.existsSync(a.build.jar));
28	  if (built) return built.build.jar;
29	  const fallback = mod.repoDir && path.join(mod.repoDir, 'target', `${mod.name}.jar`);
30	  return fallback && fs.existsSync(fallback) ? fallback : null;
31	}
32	
33	function publicMod(mod) {
34	  const { feed, ...rest } = mod;
35	  const jar = jarOf(mod);
36	  return { ...rest, feedCount: feed.length, running: active?.modId === mod.id, loadable: Boolean(jar), jar };
37	}
38	
39	// Whether this mod's build is the one installed on the server (two mods can share a plugin name, so compare jars).
40	function isLoaded(mod) {
41	  const deployed = game.status().deployed;
42	  const jar = jarOf(mod);
43	  return Boolean(deployed && jar && (deployed.jar ? deployed.jar === jar : deployed.plugin === mod.name));
44	}
45	
46	let saveTimers = new Map();
47	function save(mod) {
48	  mod.updatedAt = now();
49	  emit('studio:mod', publicMod(mod));
50	  clearTimeout(saveTimers.get(mod.id));
51	  saveTimers.set(mod.id, setTimeout(() => {
52	    fs.mkdirSync(path.dirname(modFile(mod.id)), { recursive: true });
53	    fs.writeFileSync(modFile(mod.id), JSON.stringify(mod, null, 2));
54	  }, 300));
55	}
56	
57	function load() {
58	  if (!fs.existsSync(studioDir)) return;
59	  for (const id of fs.readdirSync(studioDir)) {
60	    try {
61	      const mod = JSON.parse(fs.readFileSync(modFile(id), 'utf8'));
62	      if (!['passed', 'failed', 'stopped'].includes(mod.status)) mod.status = 'stopped';
63	      mods.set(mod.id, mod);
64	    } catch {}
65	  }
66	}
67	
68	function feed(mod, entry) {
69	  const item = { at: now(), ...entry };
70	  mod.feed.push(item);
71	  if (mod.feed.length > 1500) mod.feed.splice(0, 300);
72	  emit('studio:feed', { modId: mod.id, item });
73	}
74	
75	function setPhase(mod, phase, text) {
76	  mod.phase = phase;
77	  if (text) feed(mod, { role: 'benana', kind: 'phase', phase, text });
78	  save(mod);
79	}
80	
81	function lessons() {
82	  try { return JSON.parse(fs.readFileSync(lessonsFile, 'utf8')); } catch { return []; }
83	}
84	
85	function addLesson(lesson, mod) {
86	  const all = lessons();
87	  all.push({ lesson, mod: mod.name, at: now() });
88	  fs.mkdirSync(studioDir, { recursive: true });
89	  fs.writeFileSync(lessonsFile, JSON.stringify(all.slice(-20), null, 2));
90	}
91	
92	function parseJson(text) {
93	  const fenced = String(text).match(/```(?:json)?\s*([\s\S]*?)```/);
94	  const raw = fenced ? fenced[1] : String(text).slice(String(text).indexOf('{'), String(text).lastIndexOf('}') + 1);
95	  return JSON.parse(raw);
96	}
97	
98	const slugify = (s) => s.replace(/([a-z])([A-Z])/g, '$1-$2').replace(/[^a-zA-Z0-9]+/g, '-').replace(/^-|-$/g, '').toLowerCase().slice(0, 32);
99	
100	// Runs one agent session for a mod and records it on the attempt.
101	async function agent(mod, attempt, role, options) {
102	  const session = { role, model: options.model, startedAt: now(), sessionId: null };
103	  if (attempt) attempt.sessions.push(session);
104	  else mod.sessions.push(session);
105	  save(mod);
106	  const handle = runClaude({
107	    ...options,
108	    onEvent: (ev) => {
109	      if (ev.kind === 'session') { session.sessionId = ev.sessionId; save(mod); return; }
110	      feed(mod, { attempt: attempt?.n ?? 0, role, ...ev, input: undefined });
111	      if (role === 'playtester' && ev.kind === 'tool') emit('studio:playtester', { modId: mod.id, tool: ev.name, input: ev.input });
112	    },
113	  });
114	  active.stop = handle.stop;
115	  const result = await handle.done;
116	  Object.assign(session, { endedAt: now(), ok: result.ok, error: result.error, usage: result.usage, sessionId: result.sessionId || session.sessionId });
117	  save(mod);
118	  if (active?.stopped) throw new Error('Stopped by user.');
119	  return result;
120	}
121	
122	async function specPhase(mod) {
123	  if (mod.seed) {
124	    const seeded = JSON.parse(fs.readFileSync(path.join(SEEDED, 'spec.json'), 'utf8'));
125	    feed(mod, { role: 'benana', kind: 'note', text: 'Seeded bug fallback: using the labeled LaunchSword fixture spec instead of the spec agent.' });
126	    return seeded;
127	  }
128	  const work = path.join(studioDir, mod.id, 'spec');
129	  fs.mkdirSync(work, { recursive: true });
130	  const res = await agent(mod, null, 'spec', { cwd: work, prompt: prompts.spec(mod.prompt), model: MODELS.build, tools: [] });
131	  if (!res.ok) throw new Error(`Spec agent failed: ${res.error}`);
132	  const spec = parseJson(res.final);
133	  if (!/^[A-Za-z]{2,24}$/.test(spec.modName || '')) spec.modName = 'StudioMod';
134	  if (!spec.testPlan?.checks?.length) throw new Error('Spec agent returned no test checks.');
135	  spec.testPlan.modName = spec.modName;
136	  return spec;
137	}
138	
139	async function trace(sessionId) {
140	  if (!sessionId || !neatlogs.configured()) return '';
141	  const ev = await neatlogs.evidence({ sessionId });
142	  if (!ev.matched) return '';
143	  return ev.traces.map((t) => {
144	    const spans = (t.spans || []).slice(0, 25).map((s) => `  - ${s.name || s.span_name || 'span'}${s.status === 'error' || s.status_code === 'ERROR' ? ' (error)' : ''}`).join('\n');
145	    return `trace ${t.traceId || t.trace_id || t.id}\n${spans}`;
146	  }).join('\n').slice(0, 4000);
147	}
148	
149	async function codePhase(mod, attempt, previous) {
150	  if (attempt.role === 'seeded') {
151	    fs.copyFileSync(path.join(SEEDED, 'LaunchSword.java'), path.join(mod.repoDir, 'src', 'main', 'java', 'dev', 'benana', 'mod', 'LaunchSword.java'));
152	    feed(mod, { attempt: attempt.n, role: 'benana', kind: 'note', text: 'Seeded bug fallback: attempt 1 uses the labeled fixture source (velocity set inside the damage event).' });
153	    return;
154	  }
155	  const lessonList = lessons().map((l) => l.lesson);
156	  if (attempt.role === 'builder') {
157	    const res = await agent(mod, attempt, 'builder', { cwd: mod.repoDir, prompt: prompts.builder({ mod, lessons: lessonList }), model: MODELS.build, tools: ['Read', 'Edit', 'Write', 'Glob', 'Grep', 'Bash'], allowedTools: ['Read', 'Edit', 'Write', 'Glob', 'Grep', 'Bash'] });
158	    if (!res.ok) throw new Error(`Builder failed: ${res.error}`);
159	    attempt.summary = res.final.slice(0, 2000);
160	    return;
161	  }
162	  const cps = await repo.checkpoints(mod.repoDir);
163	  const context = {
164	    history: await repo.history(mod.repoDir),
165	    checkpoints: cps.ok ? cps.items.slice(0, 8).map((c) => `${c.checkpoint_id} "${c.message}" session ${c.session_id} (${c.agent})`).join('\n') : '',
166	    trace: await trace(previous.sessions.find((s) => s.role === 'playtester')?.sessionId).catch(() => ''),
167	  };
168	  attempt.context = { entireCheckpoints: cps.ok ? cps.items.length : 0, neatlogsTrace: Boolean(context.trace) };
169	  const res = await agent(mod, attempt, 'fixer', { cwd: mod.repoDir, prompt: prompts.fixer({ mod, attempt, previous, context }), model: MODELS.build, tools: ['Read', 'Edit', 'Write', 'Glob', 'Grep', 'Bash'], allowedTools: ['Read', 'Edit', 'Write', 'Glob', 'Grep', 'Bash'] });
170	  if (!res.ok) throw new Error(`Fixer failed: ${res.error}`);
171	  attempt.summary = res.final.slice(0, 2000);
172	  const lesson = res.final.match(/^LESSON:\s*(.+)$/m);
173	  if (lesson) attempt.lesson = lesson[1].trim();
174	}
175	
176	async function playtestPhase(mod, attempt) {
177	  const dir = path.join(mod.repoDir, 'playtest', `attempt-${attempt.n}`);
178	  fs.mkdirSync(dir, { recursive: true });
179	  const verdictFile = path.join(dir, 'verdict.json');
180	  const testPlanFile = path.join(mod.repoDir, 'playtest', 'test-plan.json');
181	  fs.rmSync(verdictFile, { force: true });
182	
183	  if (game.status().mock) {
184	    const v = game.mockVerdict(mod.testPlan, attempt.n);
185	    fs.writeFileSync(verdictFile, JSON.stringify(v, null, 2));
186	    feed(mod, { attempt: attempt.n, role: 'playtester', kind: 'note', text: '[mock runtime] canned verdict' });
187	    return game.readVerdict(verdictFile, mod.testPlan);
188	  }
189	
190	  for (let run = 1; run <= 2; run++) {
191	    const mcpFile = path.join(studioDir, mod.id, `mcp-attempt-${attempt.n}.json`);
192	    fs.mkdirSync(path.dirname(mcpFile), { recursive: true });
193	    fs.writeFileSync(mcpFile, JSON.stringify(game.mcpConfig({ runId: `${mod.id}_${attempt.n}`, verdictFile, testPlanFile })));
194	    const poll = setInterval(() => {
195	      if (!fs.existsSync(verdictFile)) return;
196	      const live = game.readVerdict(verdictFile, mod.testPlan);
197	      attempt.verdict = { ...live, live: true };
198	      save(mod);
199	    }, 1000);
200	    try {
201	      await agent(mod, attempt, 'playtester', { cwd: mod.repoDir, prompt: game.playtestPrompt(mod.testPlan), model: MODELS.playtest, tools: [], allowedTools: game.playtesterTools, mcpConfigFile: mcpFile });
202	    } finally {
203	      clearInterval(poll);
204	    }
205	    const verdict = game.readVerdict(verdictFile, mod.testPlan);
206	    if (verdict.finished) return verdict;
207	    feed(mod, { attempt: attempt.n, role: 'benana', kind: 'note', text: run === 1 ? 'The playtester stopped before finishing; running it again.' : 'The playtester did not finish the test plan.' });
208	  }
209	  return game.readVerdict(verdictFile, mod.testPlan);
210	}
211	
212	async function runAttempt(mod, n, previous) {
213	  const attempt = { n, role: n === 1 ? (mod.seed ? 'seeded' : 'builder') : 'fixer', status: 'running', startedAt: now(), sessions: [] };
214	  mod.attempts.push(attempt);
215	  save(mod);
216	
217	  setPhase(mod, n === 1 ? 'build' : 'fix', n === 1 ? `Attempt 1: writing ${mod.name}` : `Attempt ${n}: fixing what the playtester found`);
218	  await codePhase(mod, attempt, previous);
219	
220	  setPhase(mod, 'compile', `Attempt ${n}: compiling with Maven`);
221	  attempt.build = await repo.build(mod.repoDir, mod.name);
222	  if (!attempt.build.ok) {
223	    attempt.failure = { kind: 'build', summary: 'The plugin did not compile.' };
224	    attempt.commit = await repo.commit(mod.repoDir, `Attempt ${n} (${attempt.role}): build failed`);
225	    return attempt;
226	  }
227	  attempt.commit = await repo.commit(mod.repoDir, `Attempt ${n} (${attempt.role}): ${attempt.role === 'fixer' ? 'fix from playtest evidence' : 'implement'} ${mod.name}`);
228	  feed(mod, { attempt: n, role: 'benana', kind: 'note', text: `Committed ${attempt.commit.sha.slice(0, 7)}${attempt.commit.checkpoint ? `, Entire checkpoint ${attempt.commit.checkpoint}` : ''}` });
229	
230	  setPhase(mod, 'deploy', `Attempt ${n}: deploying to the Paper server`);
231	  attempt.deploy = await game.deployPlugin({ jarPath: attempt.build.jar, emit });
232	  if (!attempt.deploy.loaded) {
233	    attempt.failure = { kind: 'load', summary: 'The plugin did not load on the server.' };
234	    return attempt;
235	  }
236	
237	  setPhase(mod, 'playtest', `Attempt ${n}: the AI player is testing ${mod.name} in-game`);
238	  attempt.verdict = await playtestPhase(mod, attempt);
239	  const tally = attempt.verdict.checks.map((c) => `${c.id}=${c.status}`).join(', ');
240	  attempt.playtestCommit = await repo.commit(mod.repoDir, `Playtest attempt ${n}: ${attempt.verdict.passed ? 'PASS' : 'FAIL'}${tally ? ` (${tally})` : ''}`);
241	  if (!attempt.verdict.passed) {
242	    const failed = attempt.verdict.checks.filter((c) => c.status !== 'pass');
243	    attempt.failure = attempt.verdict.finished
244	      ? { kind: 'playtest', summary: failed.length ? failed.map((c) => `${c.id}: ${c.observed}`).join(' · ') : `${attempt.verdict.serverErrors.length} server error(s)` }
245	      : { kind: 'playtest', summary: attempt.verdict.error || 'The playtester did not finish.' };
246	  }
247	  return attempt;
248	}
249	
250	async function run(mod) {
251	  active = { modId: mod.id, stop: () => {}, stopped: false };
252	  try {
253	    if (game.status().bot !== 'online' && !game.status().mock) {
254	      setPhase(mod, 'game', 'Starting the Minecraft server');
255	      await game.start(emit);
256	    }
257	    mod.status = 'running';
258	    setPhase(mod, 'spec', 'Writing the spec and an in-game test plan');
259	    const spec = await specPhase(mod);
260	    mod.name = spec.modName;
261	    mod.spec = { summary: spec.summary, behavior: spec.behavior || [] };
262	    mod.testPlan = spec.testPlan;
263	    feed(mod, { role: 'spec', kind: 'plan', text: `${mod.testPlan.checks.length} checks: ${mod.testPlan.checks.map((c) => c.title).join(' · ')}` });
264	
265	    setPhase(mod, 'repo', 'Creating the mod repository with Entire and Neatlogs hooks');
266	    const created = await repo.create({ slug: `${slugify(mod.name)}-${mod.id.slice(-4)}`, name: mod.name, summary: mod.spec.summary });
267	    mod.repoDir = created.dir;
268	    mod.partners = created.partners;
269	    fs.mkdirSync(path.join(mod.repoDir, 'playtest'), { recursive: true });
270	    fs.writeFileSync(path.join(mod.repoDir, 'playtest', 'test-plan.json'), JSON.stringify(mod.testPlan, null, 2));
271	    await repo.commit(mod.repoDir, 'Add the in-game test plan');
272	    save(mod);
273	
274	    let previous = null;
275	    for (let n = 1; n <= MAX_ATTEMPTS; n++) {
276	      const attempt = await runAttempt(mod, n, previous);
277	      attempt.status = attempt.failure ? 'failed' : 'passed';
278	      attempt.endedAt = now();
279	      save(mod);
280	      if (!attempt.failure) {
281	        mod.status = 'passed';
282	        if (attempt.lesson) addLesson(attempt.lesson, mod);
283	        setPhase(mod, 'done', n === 1 ? `${mod.name} passed every check on the first attempt` : `${mod.name} passed after ${n} attempts`);
284	        return;
285	      }
286	      feed(mod, { attempt: n, role: 'benana', kind: 'failure', text: `Attempt ${n} failed (${attempt.failure.kind}): ${attempt.failure.summary}` });
287	      previous = attempt;
288	    }
289	    mod.status = 'failed';
290	    setPhase(mod, 'done', `${mod.name} still fails after ${MAX_ATTEMPTS} attempts`);
291	  } catch (e) {
292	    mod.status = active?.stopped ? 'stopped' : 'failed';
293	    mod.error = e.message;
294	    feed(mod, { role: 'benana', kind: 'error', text: e.message });
295	    log(`studio: ${e.message}`, 'error');
296	    save(mod);
297	  } finally {
298	    active = null;
299	    save(mod);
300	  }
301	}
302	
303	// "Run mod": a short AI-driven showcase of the mod in the live view. Only one runs at a time.
304	let demoRun = null; // { modId, stop, stopped }
305	
306	function emitDemo(extra = {}) {
307	  emit('studio:demo', { modId: demoRun?.modId || null, running: Boolean(demoRun), ...extra });
308	}
309	
310	function stopDemo() {
311	  if (!demoRun) return false;
312	  demoRun.stopped = true;
313	  demoRun.stop();
314	  return true;
315	}
316	
317	async function runDemo({ id }) {
318	  if (active) throw new Error('A mod is building. Run it after it finishes.');
319	  if (demoRun) throw new Error('A demo is already running.');
320	  const mod = mods.get(id);
321	  if (!mod?.testPlan) throw new Error('This mod has no spec yet.');
322	  const jar = jarOf(mod);
323	  if (!jar) throw new Error(`${mod.name} has no built jar yet.`);
324	  const run = { modId: id, stop: () => {}, stopped: false };
325	  demoRun = run;
326	  emitDemo();
327	  let summary = '';
328	  let error = null;
329	  try {
330	    if (!isLoaded(mod)) {
331	      const out = await game.deployPlugin({ jarPath: jar, emit });
332	      if (!out.loaded) throw new Error(`${mod.name} did not load: ${out.errors[0] || 'see the server log'}`);
333	    } else if (game.status().bot !== 'online' && !game.status().mock) {
334	      await game.start(emit);
335	    }
336	    if (run.stopped) return { stopped: true };
337	    if (game.status().mock) return { summary: '[mock runtime] no demo' };
338	    const dir = path.join(studioDir, mod.id, 'demo');
339	    fs.mkdirSync(dir, { recursive: true });
340	    const mcpFile = path.join(dir, 'mcp.json');
341	    fs.writeFileSync(mcpFile, JSON.stringify(game.mcpConfig({ runId: `${mod.id}_demo`, verdictFile: path.join(dir, 'verdict.json'), testPlanFile: path.join(dir, 'test-plan.json') })));
342	    // Runs outside the mod repo so a demo is never traced or checkpointed as part of the mod's history.
343	    const handle = runClaude({ cwd: dir, prompt: game.demoPrompt(mod), model: MODELS.playtest, tools: [], allowedTools: game.demoTools, mcpConfigFile: mcpFile, timeoutMs: 5 * 60 * 1000 });
344	    run.stop = handle.stop;
345	    if (run.stopped) handle.stop();
346	    const res = await handle.done;
347	    if (run.stopped) return { stopped: true };
348	    if (!res.ok) throw new Error(res.error);
349	    summary = res.final.trim();
350	    return { summary };
351	  } catch (e) {
352	    error = e.message;
353	    throw e;
354	  } finally {
355	    demoRun = null;
356	    emitDemo({ summary, error });
357	  }
358	}
359	
360	function create({ prompt, seed = false }) {
361	  if (active) throw new Error('Another mod is running. Stop it or wait for it to finish.');
362	  if (game.status().deploying || game.status().resetting) throw new Error('The game is being reloaded. Try again in a few seconds.');
363	  stopDemo();
364	  const text = String(prompt || '').trim();
365	  if (!seed && text.length < 8) throw new Error('Describe the mod in a sentence.');
366	  const id = `mod_${now().toString(36)}`;
367	  const mod = {
368	    id, prompt: seed ? text || 'A golden sword that launches any mob it hits into the sky with particles, with a 3 second cooldown.' : text,
369	    seed: Boolean(seed), name: 'New mod', status: 'queued', phase: 'queued', createdAt: now(), updatedAt: now(),
370	    spec: null, testPlan: null, repoDir: null, partners: null, sessions: [], attempts: [], feed: [], error: null,
371	  };
372	  mods.set(id, mod);
373	  save(mod);
374	  run(mod);
375	  return publicMod(mod);
376	}
377	
378	function repoOf(id) {
379	  const mod = mods.get(id);
380	  if (!mod?.repoDir) throw new Error('This mod has no repository yet.');
381	  return mod.repoDir;
382	}
383	
384	function handlers(deps) {
385	  emit = deps.emit;
386	  log = deps.log;
387	  load();
388	  return {
389	    'studio:list': () => [...mods.values()].sort((a, b) => b.createdAt - a.createdAt).map(publicMod),
390	    'studio:get': ({ id }) => {
391	      const mod = mods.get(id);
392	      if (!mod) throw new Error('Unknown mod.');
393	      return { ...publicMod(mod), feed: mod.feed };
394	    },
395	    'studio:create': create,
396	    // Puts a mod's latest build on the server so the user can play it or watch it in the live view.
397	    'studio:load': async ({ id }) => {
398	      if (active) throw new Error('A mod is building. Switch mods after it finishes.');
399	      const mod = mods.get(id);
400	      if (!mod) throw new Error('Unknown mod.');
401	      const jar = jarOf(mod);
402	      if (!jar) throw new Error(`${mod.name} has no built jar yet.`);
403	      stopDemo();
404	      const out = await game.deployPlugin({ jarPath: jar, emit });
405	      if (!out.loaded) throw new Error(`${mod.name} did not load: ${out.errors[0] || 'see the server log'}`);
406	      return out;
407	    },
408	    'studio:demo': runDemo,
409	    'studio:demo-stop': () => stopDemo(),
410	    'studio:demo-state': () => ({ modId: demoRun?.modId || null, running: Boolean(demoRun) }),
411	    // Wipes the world back to its beginning and reloads the server with the same mod installed.
412	    'studio:reset-world': async () => {
413	      if (active) throw new Error('A mod is building. Reset the world after it finishes.');
414	      stopDemo();
415	      return game.resetWorld({ emit });
416	    },
417	    'studio:stop': ({ id }) => {
418	      if (active?.modId !== id) return false;
419	      active.stopped = true;
420	      active.stop();
421	      return true;
422	    },
423	    'studio:evidence': ({ sessionId }) => neatlogs.evidence({ sessionId }),
424	    'studio:checkpoints': async ({ id }) => {
425	      const mod = mods.get(id);
426	      return mod?.repoDir ? repo.checkpoints(mod.repoDir) : { ok: false, items: [], error: 'No repository yet.' };
427	    },
428	    'studio:files': ({ id }) => repo.files(repoOf(id)),
429	    'studio:file': ({ id, path: rel }) => repo.readFile(repoOf(id), rel),
430	    'studio:diff': ({ id, sha }) => repo.diff(repoOf(id), sha),
431	    'studio:lessons': () => lessons(),
432	    'studio:partners': async () => ({ neatlogs: await neatlogs.status() }),
