1	// Mod repositories: one git repo per mod, created from templates/paper-plugin, with Entire and Neatlogs
2	// hooks installed at project scope so every agent session in the repo is checkpointed and traced.
3	const fs = require('node:fs');
4	const path = require('node:path');
5	const { execFile } = require('node:child_process');
6	const { appRoot, dataDir, env } = require('../env.cjs');
7	const { resolveExecutable } = require('../processes.cjs');
8	
9	const TEMPLATE = path.join(appRoot, 'templates', 'paper-plugin');
10	const modsDir = path.join(dataDir, 'mods');
11	
12	function exec(cmd, args, cwd, { timeoutMs = 120000, input } = {}) {
13	  return new Promise((resolve) => {
14	    const bin = resolveExecutable(cmd);
15	    // npm and Maven install .cmd shims on Windows, which only run through a shell. Their args here have no spaces.
16	    const shell = /\.(cmd|bat)$/i.test(bin);
17	    const child = execFile(shell ? `"${bin}"` : bin, args, { cwd, shell, timeout: timeoutMs, maxBuffer: 32 * 1024 * 1024, windowsHide: true, env: { ...process.env, ACCESSIBLE: '1' } },
18	      (error, stdout, stderr) => resolve({
19	        ok: !error,
20	        code: error?.code ?? 0,
21	        out: String(stdout || ''),
22	        err: String(stderr || error?.message || ''),
23	        missing: error?.code === 'ENOENT',
24	      }));
25	    child.stdin.end(input ?? '');
26	  });
27	}
28	
29	const git = (cwd, ...args) => exec('git', args, cwd);
30	
31	function fill(text, vars) {
32	  return text.replace(/__(NAME|ARTIFACT|SUMMARY)__/g, (_, k) => vars[k]);
33	}
34	
35	function copyTemplate(dir, vars) {
36	  const walk = (src, dst) => {
37	    fs.mkdirSync(dst, { recursive: true });
38	    for (const entry of fs.readdirSync(src, { withFileTypes: true })) {
39	      const from = path.join(src, entry.name);
40	      const name = entry.name === 'gitignore' ? '.gitignore' : fill(entry.name, vars);
41	      const to = path.join(dst, name);
42	      if (entry.isDirectory()) walk(from, to);
43	      else fs.writeFileSync(to, fill(fs.readFileSync(from, 'utf8'), vars));
44	    }
45	  };
46	  walk(TEMPLATE, dir);
47	}
48	
49	// Creates the repo and installs partner hooks. Returns which integrations are active.
50	async function create({ slug, name, summary }) {
51	  const dir = path.join(modsDir, slug);
52	  fs.rmSync(dir, { recursive: true, force: true });
53	  copyTemplate(dir, { NAME: name, ARTIFACT: slug, SUMMARY: summary.replace(/\r?\n/g, ' ').slice(0, 200) });
54	  await git(dir, 'init', '-q', '-b', 'main');
55	  await git(dir, 'config', 'user.name', 'Benana Mod Studio');
56	  await git(dir, 'config', 'user.email', 'studio@benana.dev');
57	  await git(dir, 'config', 'core.autocrlf', 'false');
58	
59	  const partners = { entire: { enabled: false }, neatlogs: { enabled: false } };
60	
61	  const ent = await exec('entire', ['enable', '--agent', 'claude-code', '--project'], dir, { timeoutMs: 60000 });
62	  if (ent.ok) {
63	    const file = path.join(dir, '.entire', 'settings.json');
64	    const settings = JSON.parse(fs.readFileSync(file, 'utf8'));
65	    // Benana commits each attempt from a non-interactive process; prompting would hang the commit hook.
66	    Object.assign(settings, { commit_linking: 'always', telemetry: false });
67	    fs.writeFileSync(file, JSON.stringify(settings, null, 2));
68	    partners.entire = { enabled: true };
69	  } else {
70	    partners.entire = { enabled: false, error: ent.missing ? 'Entire CLI is not installed.' : (ent.err || ent.out).trim().slice(0, 400) };
71	  }
72	
73	  const key = env('NEATLOGS_INGEST_KEY') || env('NEATLOGS_API_KEY');
74	  if (key) {
75	    const nl = await exec('neatlogs-claude-code', ['setup', '--project', '--api-key', key], dir, { timeoutMs: 60000 });
76	    partners.neatlogs = nl.ok ? { enabled: true } : { enabled: false, error: (nl.missing ? 'neatlogs-claude-code is not installed.' : nl.err || nl.out).trim().slice(0, 400) };
77	  } else {
78	    partners.neatlogs = { enabled: false, error: 'Set NEATLOGS_INGEST_KEY (or NEATLOGS_API_KEY) in .env to trace agent sessions.' };
79	  }
80	
81	  await commit(dir, `Scaffold ${name} from the Benana Paper template`);
82	  return { dir, partners };
83	}
84	
85	async function commit(dir, message) {
86	  await git(dir, 'add', '-A');
87	  const res = await git(dir, 'commit', '-q', '--allow-empty', '-m', message);
88	  const sha = (await git(dir, 'rev-parse', 'HEAD')).out.trim();
89	  const trailer = (await git(dir, 'log', '-1', '--format=%(trailers:key=Entire-Checkpoint,valueonly)')).out.trim();
90	  return { ok: res.ok, sha, checkpoint: trailer || null, error: res.ok ? null : res.err.trim() };
91	}
92	
93	async function checkpoints(dir) {
94	  const res = await exec('entire', ['checkpoint', 'list', '--json', '--no-pager'], dir, { timeoutMs: 30000 });
95	  if (!res.ok) return { ok: false, items: [], error: (res.err || res.out).trim().slice(0, 400) };
96	  try { return { ok: true, items: JSON.parse(res.out) }; } catch { return { ok: false, items: [], error: 'Unrecognized checkpoint output.' }; }
97	}
98	
99	async function history(dir) {
100	  return (await git(dir, 'log', '--format=%h %s%n%(trailers:key=Entire-Checkpoint)', '-20')).out.trim();
101	}
102	
103	async function files(dir) {
104	  const res = await git(dir, 'ls-files', '-z');
105	  return res.out.split('\0').filter(Boolean);
106	}
107	
108	async function readFile(dir, rel) {
109	  if (!(await files(dir)).includes(rel)) throw new Error('Not a tracked file in this mod repository.');
110	  return fs.readFileSync(path.join(dir, rel), 'utf8').slice(0, 200000);
111	}
