// Mod repositories: one git repo per mod, created from templates/paper-plugin, with Entire and Neatlogs
// hooks installed at project scope so every agent session in the repo is checkpointed and traced.
const fs = require('node:fs');
const path = require('node:path');
const { execFile } = require('node:child_process');
const { appRoot, dataDir, env } = require('../env.cjs');
const { resolveExecutable } = require('../processes.cjs');

const TEMPLATE = path.join(appRoot, 'templates', 'paper-plugin');
const modsDir = path.join(dataDir, 'mods');

function exec(cmd, args, cwd, { timeoutMs = 120000, input } = {}) {
  return new Promise((resolve) => {
    const bin = resolveExecutable(cmd);
    // npm and Maven install .cmd shims on Windows, which only run through a shell. Their args here have no spaces.
    const shell = /\.(cmd|bat)$/i.test(bin);
    const child = execFile(shell ? `"${bin}"` : bin, args, { cwd, shell, timeout: timeoutMs, maxBuffer: 32 * 1024 * 1024, windowsHide: true, env: { ...process.env, ACCESSIBLE: '1' } },
      (error, stdout, stderr) => resolve({
        ok: !error,
        code: error?.code ?? 0,
        out: String(stdout || ''),
        err: String(stderr || error?.message || ''),
        missing: error?.code === 'ENOENT',
      }));
    child.stdin.end(input ?? '');
  });
}

const git = (cwd, ...args) => exec('git', args, cwd);

function fill(text, vars) {
  return text.replace(/__(NAME|ARTIFACT|SUMMARY)__/g, (_, k) => vars[k]);
}

function copyTemplate(dir, vars) {
  const walk = (src, dst) => {
    fs.mkdirSync(dst, { recursive: true });
    for (const entry of fs.readdirSync(src, { withFileTypes: true })) {
      const from = path.join(src, entry.name);
      const name = entry.name === 'gitignore' ? '.gitignore' : fill(entry.name, vars);
      const to = path.join(dst, name);
      if (entry.isDirectory()) walk(from, to);
      else fs.writeFileSync(to, fill(fs.readFileSync(from, 'utf8'), vars));
    }
  };
  walk(TEMPLATE, dir);
}

// Creates the repo and installs partner hooks. Returns which integrations are active.
async function create({ slug, name, summary }) {
  const dir = path.join(modsDir, slug);
  fs.rmSync(dir, { recursive: true, force: true });
  copyTemplate(dir, { NAME: name, ARTIFACT: slug, SUMMARY: summary.replace(/\r?\n/g, ' ').slice(0, 200) });
  await git(dir, 'init', '-q', '-b', 'main');
  await git(dir, 'config', 'user.name', 'Benana Mod Studio');
  await git(dir, 'config', 'user.email', 'studio@benana.dev');
  await git(dir, 'config', 'core.autocrlf', 'false');

  const partners = { entire: { enabled: false }, neatlogs: { enabled: false } };

  const ent = await exec('entire', ['enable', '--agent', 'claude-code', '--project'], dir, { timeoutMs: 60000 });
  if (ent.ok) {
    const file = path.join(dir, '.entire', 'settings.json');
    const settings = JSON.parse(fs.readFileSync(file, 'utf8'));
    // Benana commits each attempt from a non-interactive process; prompting would hang the commit hook.
    Object.assign(settings, { commit_linking: 'always', telemetry: false });
    fs.writeFileSync(file, JSON.stringify(settings, null, 2));
    partners.entire = { enabled: true };
  } else {
    partners.entire = { enabled: false, error: ent.missing ? 'Entire CLI is not installed.' : (ent.err || ent.out).trim().slice(0, 400) };
  }

  const key = env('NEATLOGS_INGEST_KEY') || env('NEATLOGS_API_KEY');
  if (key) {
    const nl = await exec('neatlogs-claude-code', ['setup', '--project', '--api-key', key], dir, { timeoutMs: 60000 });
    partners.neatlogs = nl.ok ? { enabled: true } : { enabled: false, error: (nl.missing ? 'neatlogs-claude-code is not installed.' : nl.err || nl.out).trim().slice(0, 400) };
  } else {
    partners.neatlogs = { enabled: false, error: 'Set NEATLOGS_INGEST_KEY (or NEATLOGS_API_KEY) in .env to trace agent sessions.' };
  }

  await commit(dir, `Scaffold ${name} from the Benana Paper template`);
  return { dir, partners };
}

async function commit(dir, message) {
  await git(dir, 'add', '-A');
  const res = await git(dir, 'commit', '-q', '--allow-empty', '-m', message);
  const sha = (await git(dir, 'rev-parse', 'HEAD')).out.trim();
  const trailer = (await git(dir, 'log', '-1', '--format=%(trailers:key=Entire-Checkpoint,valueonly)')).out.trim();
  return { ok: res.ok, sha, checkpoint: trailer || null, error: res.ok ? null : res.err.trim() };
}

async function checkpoints(dir) {
  const res = await exec('entire', ['checkpoint', 'list', '--json', '--no-pager'], dir, { timeoutMs: 30000 });
  if (!res.ok) return { ok: false, items: [], error: (res.err || res.out).trim().slice(0, 400) };
  try { return { ok: true, items: JSON.parse(res.out) }; } catch { return { ok: false, items: [], error: 'Unrecognized checkpoint output.' }; }
}

async function history(dir) {
  return (await git(dir, 'log', '--format=%h %s%n%(trailers:key=Entire-Checkpoint)', '-20')).out.trim();
}

async function files(dir) {
  const res = await git(dir, 'ls-files', '-z');
  return res.out.split('\0').filter(Boolean);
}

async function readFile(dir, rel) {
  if (!(await files(dir)).includes(rel)) throw new Error('Not a tracked file in this mod repository.');
  return fs.readFileSync(path.join(dir, rel), 'utf8').slice(0, 200000);
}

async function diff(dir, sha) {
  if (!/^[0-9a-f]{7,40}$/.test(sha || '')) throw new Error('Unknown commit.');
  return (await git(dir, 'show', '--format=%s%n%n%b', '--patch', '--no-color', sha)).out.slice(0, 200000);
}

async function build(dir, name) {
  const res = await exec('mvn', ['-q', '-B', 'package'], dir, { timeoutMs: 6 * 60 * 1000 });
  const log = `${res.out}\n${res.err}`.trim();
  const jar = path.join(dir, 'target', `${name}.jar`);
  if (res.missing) return { ok: false, jar: null, log: 'Maven (mvn) is not on PATH.' };
  return { ok: res.ok && fs.existsSync(jar), jar: fs.existsSync(jar) ? jar : null, log: log.slice(-12000) };
}

module.exports = { modsDir, create, commit, checkpoints, history, files, readFile, diff, build };

// Prompts for the spec, builder, and fixer agents. The playtester prompt lives with the game runtime.

const TESTABLE = `The playtester controls a real player bot ("@bot") on a local Paper 1.21.4 superflat server with these tools:
game_setup(console commands run as the bot; ^ and ~ are relative to it), reset_arena (flat arena, no mobs, empty inventory), bot_state,
nearby_entities (id, type, position, velocity, health), attack_sequence(entityIds, intervalTicks, trackTicks) (back-to-back hits in one call, for cooldowns),
equip(item), look_at, move_to, attack(entityId, trackTicks), use_item(entityId?, trackTicks),
shoot(entityId | entityIds | position, item?, chargeTicks?) (aims and fires a bow, crossbow, trident or throwable; entityIds fires several shots back to back in one call;
reports each projectile, every explosion with its position, ammo used, chat, and health before/after, deaths and max velocity of every living entity nearby),
track_entity(entityId, ticks) (per-tick position and velocity with maxUpwardVelocity and maxHeightGain), wait_ticks, chat (including /commands), read_chat,
server_log (console, including plugin exceptions and the plugin's own getLogger() lines).`;

function spec(prompt) {
  return `You are the spec agent for Benana Mod Studio. A user described a Minecraft mod. Turn it into a Paper plugin spec and a test plan
that an AI playtester can execute in-game and judge with measurements.

User's description:
"""${prompt}"""

${TESTABLE}

Rules for the test plan:
- 2 to 4 checks. Each check targets one behavior and has an "expect" with a measurable threshold (velocity, height, count, chat text, health).
- "setup" holds console commands without a leading slash. Use @bot for the bot. Give the bot the items it needs.
- Summon mobs with {PersistenceRequired:1b}. Never use NoAI:1b (NoAI mobs ignore velocity and knockback). Prefer husks to zombies (zombies burn in daylight).
- Summon melee targets 2-3 blocks in front of the bot, e.g. "summon husk ^ ^ ^3 {PersistenceRequired:1b}". Summon ranged targets
  (bows, tridents, snowballs) 8-12 blocks away, e.g. "summon husk ^ ^ ^10 {PersistenceRequired:1b}", and use the shoot tool, never use_item.
- Explosions hit everything nearby. Space mobs that must stay unharmed at least 8 blocks from any blast, and start checks that need a clean
  world (fresh mobs, no cooldown left over) with reset_arena followed by their own setup.
- Every check must name the tool that produces its measurement. Prefer direct evidence (an explosion position, a health number, a chat line,
  a server_log line) over indirect signs such as a mob disappearing.
- Timing-sensitive checks (cooldowns) must happen inside ONE tool call: attack_sequence for melee, shoot with entityIds for ranged. Separate
  tool calls are several real seconds apart.
- Include a check for any limit the user mentioned (cooldowns, permissions, item requirements) and one negative check where it is cheap (for example, a different item does nothing).
- Velocity is in blocks per tick. A normal sword hit's knockback gives about 0.4 upward; a strong launch is above 1.0.

Respond with ONLY a JSON object, no prose:
{
  "modName": "PascalCase plugin name, letters only, max 24 chars",
  "summary": "one sentence",
  "behavior": ["precise behavior bullet", "..."],
  "testPlan": {
    "version": 1,
    "modName": "same as above",
    "summary": "same as above",
    "setup": ["..."],
    "checks": [{ "id": "kebab-case", "title": "...", "steps": "...", "expect": "..." }]
  }
}`;
}

function builder({ mod, lessons }) {
  return `You are the builder agent for Benana Mod Studio. Implement this Paper plugin in the current repository.

Mod: ${mod.name}: ${mod.spec.summary}
User's description: """${mod.prompt}"""

Behavior:
${mod.spec.behavior.map((b) => `- ${b}`).join('\n')}

The in-game playtester will run this test plan after you finish (also in playtest/test-plan.json):
${JSON.stringify(mod.testPlan.checks, null, 2)}

Read CLAUDE.md for the repository conventions. The main class dev.benana.mod.${mod.name} already exists as a stub.
${lessons.length ? `\nLessons from earlier mods built in Benana (apply them):\n${lessons.map((l) => `- ${l}`).join('\n')}\n` : ''}
Work steps:
1. Implement the behavior. Keep it to the Paper API. Log every key action and decision with getLogger().info (for example "X shot an
   explosive arrow", "cooldown 3.2s remaining", "explosion at x,y,z"); the playtester reads these lines as evidence.
2. Run \`mvn -q package\` and fix every compile error until target/${mod.name}.jar builds.
3. Do not commit. Finish with a short summary of what you implemented.`;
}

function fixer({ mod, attempt, previous, context }) {
  const failed = (previous.verdict?.checks || []).filter((c) => c.status !== 'pass');
  const evidence = previous.failure?.kind === 'build'
    ? `The build failed. Maven output (tail):\n${previous.build?.log?.slice(-4000) || '(none)'}`
    : previous.failure?.kind === 'load'
      ? `The plugin did not load on the server. Errors:\n${(previous.deploy?.errors || []).join('\n').slice(0, 4000)}`
      : `The in-game playtester reported:\n${JSON.stringify({ summary: previous.verdict?.summary, failedChecks: failed, serverErrors: previous.verdict?.serverErrors }, null, 2).slice(0, 8000)}`;
  return `You are the fixer agent for Benana Mod Studio. Attempt ${attempt.n - 1} of the ${mod.name} plugin failed. Fix it.

Mod: ${mod.name}: ${mod.spec.summary}
Behavior:
${mod.spec.behavior.map((b) => `- ${b}`).join('\n')}

Full test plan: playtest/test-plan.json. Previous verdicts: playtest/attempt-*/verdict.json.

${evidence}

Repository history (Entire checkpoints link each commit to the agent session that produced it):
${context.history || '(none)'}
${context.checkpoints ? `\nEntire checkpoints:\n${context.checkpoints}` : ''}
${context.trace ? `\nNeatlogs trace of the failed playtest session:\n${context.trace}` : ''}

Steps:
1. Find the root cause from the evidence; the playtester's measurements are ground truth, and its suspected cause is only a guess.
2. Make the smallest change that fixes it. Run \`mvn -q package\` until it builds.
3. Do not commit. End your reply with exactly one line:
LESSON: <one sentence a future builder should know to avoid this bug>`;
}

module.exports = { spec, builder, fixer };

